<?php
declare(strict_types=1);
namespace App\Services;
final class ModuleAttachmentKeyParser { public function parse(string $key):array{if($key===''||strlen($key)>4096)$this->invalid();$parts=explode('.',$key);if(count($parts)!==3||$parts[0]!=='GDA1'||!preg_match('/^[A-Za-z0-9_-]{43,512}$/',$parts[2])||!preg_match('/^[A-Za-z0-9_-]+$/',$parts[1]))$this->invalid();$payload=$parts[1].str_repeat('=',(4-strlen($parts[1])%4)%4);$json=base64_decode(strtr($payload,'-_','+/'),true);$data=is_string($json)?json_decode($json,true):null;if(!is_array($data)||array_diff(array_keys($data),['v','module','endpoint','nonce']))$this->invalid();if(($data['v']??null)!==1)throw new ModuleAttachmentException('key_version','Chave inválida.');if(!preg_match('/^gda-[a-z0-9]+(?:-[a-z0-9]+)*$/',(string)($data['module']??'')))$this->invalid();if(!is_string($data['endpoint']??null)||!is_string($data['nonce']??null)||!preg_match('/^[A-Za-z0-9_-]{12,128}$/',$data['nonce']))$this->invalid();return ['version'=>1,'module'=>$data['module'],'endpoint'=>$data['endpoint'],'nonce'=>$data['nonce'],'key'=>$key];}private function invalid():never{throw new ModuleAttachmentException('invalid_key','Chave inválida.');} }
